import{_ as s,C as n,o as e,c as i,a2 as a,b as l,w as o,a as d,E as c,a3 as g}from"./chunks/framework.Brv5O9VI.js";const A=JSON.parse('{"title":"14.5 Databases, Vector Stores & CAP Theorem","description":"","frontmatter":{},"headers":[],"relativePath":"system-design/14.5-databases-and-storage.md","filePath":"system-design/14.5-databases-and-storage.md"}'),h={name:"system-design/14.5-databases-and-storage.md"};function m(u,t,p,f,y,x){const r=n("Mermaid");return e(),i("div",null,[t[1]||(t[1]=a('<h1 id="_14-5-databases-vector-stores-cap-theorem" tabindex="-1">14.5 Databases, Vector Stores &amp; CAP Theorem <a class="header-anchor" href="#_14-5-databases-vector-stores-cap-theorem" aria-label="Permalink to &quot;14.5 Databases, Vector Stores &amp; CAP Theorem&quot;">​</a></h1><h2 id="_1-what-it-is-in-plain-words" tabindex="-1">1. What It Is in Plain Words <a class="header-anchor" href="#_1-what-it-is-in-plain-words" aria-label="Permalink to &quot;1. What It Is in Plain Words&quot;">​</a></h2><p>Data storage architecture dictates how structured information, unstructured documents, and high-dimensional vector coordinates are persisted, indexed, partitioned, and queried, balancing consistency, availability, and latency.</p><hr><h2 id="_2-how-this-project-uses-it" tabindex="-1">2. How THIS Project Uses It <a class="header-anchor" href="#_2-how-this-project-uses-it" aria-label="Permalink to &quot;2. How THIS Project Uses It&quot;">​</a></h2><p>This platform utilizes a <strong>hybrid in-memory static storage model</strong>:</p><ul><li><strong>Vector Search Store</strong>: Inverted Inner Product index (<code>faiss.IndexFlatIP</code>) loaded from binary file <code>model2_rag_faiss.index</code> ([<code>app.py:L26</code>](file:///Users/avishjain/avishjain9-repos/21-bis-compliance-engine/app.py#L26)).</li><li><strong>Master Metadata Corpus</strong>: Structured JSON knowledge base [<code>model2_corpus.json</code>](file:///Users/avishjain/avishjain9-repos/21-bis-compliance-engine/model2_corpus.json) ([<code>app.py:L28-L29</code>](file:///Users/avishjain/avishjain9-repos/21-bis-compliance-engine/app.py#L28-L29)) containing 47 authoritative standards.</li><li><strong>Relational DB / NoSQL Database</strong>: <strong>Not Used</strong>. Because the regulatory corpus is an authoritative read-only dataset that updates only when official ministerial gazettes are published, adding an external networked database (like MongoDB or Postgres) would introduce operational overhead without practical value for this scale [CONFIRM WITH DEVELOPER].</li></ul>',7)),(e(),l(g,null,{default:o(()=>[c(r,{id:"mermaid-33",class:"mermaid",graph:"erDiagram%0A%20%20%20%20VECTOR_INDEX%20%7C%7C--%7C%7C%20CORPUS_DOCUMENT%20%3A%20references_by_row_id%0A%20%20%20%20CORPUS_DOCUMENT%20%7C%7C--o%7B%20REGULATORY_CITATION%20%3A%20embeds%0A%20%20%20%20CORPUS_DOCUMENT%20%7C%7C--o%7B%20TESTING_LAB%20%3A%20specifies%0A%0A%20%20%20%20VECTOR_INDEX%20%7B%0A%20%20%20%20%20%20%20%20int%20index_id%20PK%20%220%20to%2046%22%0A%20%20%20%20%20%20%20%20float32_array%20embedding%20%22384-dimensional%20unit%20vector%22%0A%20%20%20%20%7D%0A%0A%20%20%20%20CORPUS_DOCUMENT%20%7B%0A%20%20%20%20%20%20%20%20string%20standard%20PK%20%22IS%2012269%3A2013%20%2F%20AIS%20156%22%0A%20%20%20%20%20%20%20%20string%20product_name%20%22Product%20title%22%0A%20%20%20%20%20%20%20%20string%20department%20%22CED%2C%20MTD%2C%20FAD%2C%20MoRTH_AIS%22%0A%20%20%20%20%20%20%20%20string%20qco_order%20%22Mandatory%20Gazette%20Order%22%0A%20%20%20%20%20%20%20%20string%20scheme%20%22Scheme-I%20%2F%20TAC%22%0A%20%20%20%20%20%20%20%20string%20portal%20%22Manakonline%20%2F%20Vahan%22%0A%20%20%20%20%7D%0A"})]),fallback:o(()=>[...t[0]||(t[0]=[d(" Loading... ",-1)])]),_:1})),t[2]||(t[2]=a('<hr><h2 id="_3-full-comparison-with-database-alternatives" tabindex="-1">3. Full Comparison with Database Alternatives <a class="header-anchor" href="#_3-full-comparison-with-database-alternatives" aria-label="Permalink to &quot;3. Full Comparison with Database Alternatives&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Storage Technology</th><th style="text-align:left;">Data Model</th><th style="text-align:left;">Vector Capability</th><th style="text-align:left;">Search Latency ($k=1$)</th><th style="text-align:left;">Operational Cost</th><th style="text-align:left;">CAP Classification</th><th style="text-align:left;">Fit for This Engine</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>FAISS + Local JSON</strong> (Used)</td><td style="text-align:left;">In-Memory Flat Vectors + JSON</td><td style="text-align:left;">Native C++ Inner Product</td><td style="text-align:left;"><strong>&lt;0.2 ms</strong></td><td style="text-align:left;"><strong>$0.00</strong></td><td style="text-align:left;"><strong>AP (Read-Local)</strong></td><td style="text-align:left;"><strong>Optimal</strong></td></tr><tr><td style="text-align:left;"><strong>PostgreSQL + pgvector</strong></td><td style="text-align:left;">Relational + Vector Ext</td><td style="text-align:left;">HNSW / IVFFlat</td><td style="text-align:left;">~8-15 ms</td><td style="text-align:left;">$15+/mo</td><td style="text-align:left;">CP (ACID)</td><td style="text-align:left;">Good for historic audit logs</td></tr><tr><td style="text-align:left;"><strong>MongoDB Atlas</strong></td><td style="text-align:left;">Document Store</td><td style="text-align:left;">Atlas Vector Search</td><td style="text-align:left;">~35-80 ms</td><td style="text-align:left;">$30+/mo</td><td style="text-align:left;">CP</td><td style="text-align:left;">Overkill (No writes/mutations)</td></tr><tr><td style="text-align:left;"><strong>Pinecone</strong></td><td style="text-align:left;">Managed Cloud Vector</td><td style="text-align:left;">Cloud Vector Index</td><td style="text-align:left;">~50-120 ms</td><td style="text-align:left;">$70+/mo</td><td style="text-align:left;">AP (Cloud)</td><td style="text-align:left;">Violates Air-Gap mandate</td></tr><tr><td style="text-align:left;"><strong>SQLite (In-Process)</strong></td><td style="text-align:left;">Relational Embedded</td><td style="text-align:left;">Extension (sqlite-vss)</td><td style="text-align:left;">~2-5 ms</td><td style="text-align:left;">$0.00</td><td style="text-align:left;">Single-writer ACID</td><td style="text-align:left;">Recommended upgrade path</td></tr></tbody></table><hr><h2 id="_4-cap-pacelc-theorem-mapping" tabindex="-1">4. CAP &amp; PACELC Theorem Mapping <a class="header-anchor" href="#_4-cap-pacelc-theorem-mapping" aria-label="Permalink to &quot;4. CAP &amp; PACELC Theorem Mapping&quot;">​</a></h2><ul><li><strong>CAP Theorem</strong>: The system sits firmly in the <strong>AP (Available / Partition Tolerant)</strong> quadrant. Because nodes hold full, identical read-only copies of the index in local RAM, network partitions between servers cannot cause query failures or inconsistency. Every node remains 100% available to answer queries.</li><li><strong>PACELC Theorem</strong>: In the event of Partition (<strong>P</strong>), choose Availability (<strong>A</strong>) over Consistency (<strong>C</strong>); Else (<strong>E</strong>), choose Latency (<strong>L</strong>) over Consistency (<strong>C</strong>). The system prioritizes sub-millisecond read latency over real-time distributed write synchronization.</li></ul><hr><h2 id="_5-what-breaks-at-scale" tabindex="-1">5. What Breaks at Scale <a class="header-anchor" href="#_5-what-breaks-at-scale" aria-label="Permalink to &quot;5. What Breaks at Scale&quot;">​</a></h2><ul><li><strong>At 10x Load</strong>: In-memory storage performs flawlessly; RAM usage remains constant at ~65 MB regardless of query volume.</li><li><strong>At 100x Load</strong>: Memory remains stable; the read-only index cannot be corrupted by concurrent reads.</li><li><strong>At 1000x Load / 100,000 Standards</strong>: The corpus size reaches ~300 MB. Flat vector scanning latency rises from 0.2ms to ~15ms. Demands upgrading from <code>IndexFlatIP</code> to <code>faiss.IndexHNSWFlat</code> or an external vector database cluster like Qdrant or pgvector.</li></ul><hr><h2 id="_6-how-a-senior-engineer-would-improve-it" tabindex="-1">6. How a Senior Engineer Would Improve It <a class="header-anchor" href="#_6-how-a-senior-engineer-would-improve-it" aria-label="Permalink to &quot;6. How a Senior Engineer Would Improve It&quot;">​</a></h2><p>For enterprise multi-tenancy, introduce a <strong>dual storage tier</strong>:</p><ol><li><strong>Static Regulatory Catalog</strong>: Retain local in-memory FAISS for microsecond vector retrieval.</li><li><strong>Transactional State Store</strong>: Add <strong>PostgreSQL with SQLAlchemy</strong> to persist user audit sessions, uploaded factory certificates, and audit logs.</li></ol><hr><h2 id="_7-30-second-spoken-answer" tabindex="-1">7. 30-Second Spoken Answer <a class="header-anchor" href="#_7-30-second-spoken-answer" aria-label="Permalink to &quot;7. 30-Second Spoken Answer&quot;">​</a></h2><blockquote><p>&quot;We chose an in-memory FAISS vector index paired with static JSON records over an external database like MongoDB or PostgreSQL because our regulatory knowledge base is read-heavy and immutable. Reading directly from resident RAM guarantees zero database connection pooling overhead and sub-millisecond retrieval with zero cloud infrastructure expenses.&quot;</p></blockquote>',16))])}const _=s(h,[["render",m]]);export{A as __pageData,_ as default};
